//! `docs/explorer.html`, the page that navigates the coverage graph, stays true to the tool (ADR 0054, unit E-1).
//!
//! The page is generated by `tools/explorer/build.py`: a hand-written template (`tools/explorer/explorer.html`, the same
//! bytes for every corpus) with one JSON document inserted, built from `req trace --format json`, `req satisfy --format
//! json` and the architecture overlays' component maps. It is checked the way a projection is: regenerated and compared.
//! What a test can read back of it is the data document and the template around it; how the script behaves in a browser
//! is not in the gate (the named gap in ADR 0054's note), so the document is what is held to *Falsification* 1 to 4.
//!
//! The oracles here are computed from `req`'s own JSON, independently of the builder.

use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::atomic::{AtomicU64, Ordering};

use serde_json::Value;

const PAGE: &str = "docs/explorer.html";
const TEMPLATE: &str = "tools/explorer/explorer.html";
/// The token in the template that the builder replaces with the data document (the only byte the page adds).
const TOKEN: &str = "__REQ_EXPLORER_DATA__";
const OPEN: &str = "<script type=\"application/json\" id=\"req-explorer-data\">";

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).to_path_buf()
}

fn req_bin() -> PathBuf {
    std::env::var_os("CARGO_BIN_EXE_req")
        .map(PathBuf::from)
        .expect("integration tests run with CARGO_BIN_EXE_req set")
}

/// `python3` as an absolute path, resolved before the child's `PATH` is rewritten.
fn python3() -> PathBuf {
    let path = std::env::var_os("PATH").unwrap_or_default();
    for dir in std::env::split_paths(&path) {
        let candidate = dir.join("python3");
        if candidate.is_file() {
            return candidate;
        }
    }
    panic!("python3 is required for tools/explorer/build.py - install it first");
}

fn read(path: &Path) -> String {
    fs::read_to_string(path)
        .unwrap_or_else(|error| panic!("{} cannot be read: {error}", path.display()))
}

fn copy_tree(from: &Path, to: &Path) {
    fs::create_dir_all(to).expect("makes the dir");
    for entry in fs::read_dir(from).unwrap_or_else(|e| panic!("{}: {e}", from.display())) {
        let entry = entry.expect("a dir entry");
        let target = to.join(entry.file_name());
        if entry.file_type().expect("a file type").is_dir() {
            copy_tree(&entry.path(), &target);
        } else {
            fs::copy(entry.path(), &target).expect("copies a file");
        }
    }
}

/// A scratch copy of the parts of the repository the build reads, never this checkout.
struct Copy(PathBuf);

impl Copy {
    fn new(name: &str) -> Self {
        static N: AtomicU64 = AtomicU64::new(0);
        let dir = std::env::temp_dir().join(format!(
            "req-explorer-page-{}-{}-{name}",
            std::process::id(),
            N.fetch_add(1, Ordering::SeqCst)
        ));
        let _ = fs::remove_dir_all(&dir);
        fs::create_dir_all(&dir).expect("creates the scratch dir");
        for tree in [
            "claims",
            "aliases",
            ".req",
            "src",
            "decisions",
            "baselines",
            "docs/architecture",
            "tools/explorer",
        ] {
            copy_tree(&root().join(tree), &dir.join(tree));
        }
        fs::copy(root().join(PAGE), dir.join(PAGE)).expect("copies the committed page");
        Copy(dir)
    }

    fn path(&self, relative: &str) -> PathBuf {
        self.0.join(relative)
    }
}

impl Drop for Copy {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

struct Run {
    code: Option<i32>,
    said: String,
}

/// `python3 <repo>/tools/explorer/build.py <args>` with `req` first on `PATH`, run from `repo` (the script reads the
/// repository it lives in, so a copy checks itself).
fn build(repo: &Path, args: &[&str]) -> Run {
    let interpreter = python3();
    let mut entries = vec![req_bin().parent().expect("a parent dir").to_path_buf()];
    entries.extend(std::env::split_paths(
        &std::env::var_os("PATH").unwrap_or_default(),
    ));
    let path = std::env::join_paths(entries).expect("valid PATH");
    let output = Command::new(interpreter)
        .arg("tools/explorer/build.py")
        .args(args)
        .current_dir(repo)
        .env("PATH", path)
        .env_remove("REQ_ROOT")
        .output()
        .expect("runs tools/explorer/build.py");
    Run {
        code: output.status.code(),
        said: format!(
            "{}{}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        ),
    }
}

/// `req <args>` in this repository, its JSON document (the exit code is a verdict, not a failure to print).
fn req_json(args: &[&str]) -> Value {
    let output = Command::new(req_bin())
        .arg("--root")
        .arg(root())
        .args(args)
        .env_remove("REQ_ROOT")
        .output()
        .expect("runs req");
    serde_json::from_slice(&output.stdout).unwrap_or_else(|error| {
        panic!(
            "`req {}` printed no JSON document ({error}): {}",
            args.join(" "),
            String::from_utf8_lossy(&output.stderr)
        )
    })
}

/// The selection the page is built with: the first line of `.req/variants`, as `key=value` words.
fn selection_words() -> Vec<String> {
    let text = read(&root().join(".req/variants"));
    text.lines()
        .map(|line| line.split('#').next().unwrap_or("").trim().to_string())
        .find(|line| !line.is_empty())
        .expect(".req/variants has a line")
        .split_whitespace()
        .map(str::to_string)
        .collect()
}

fn trace() -> Value {
    let words = selection_words();
    let mut args = vec!["trace", "--format", "json"];
    args.extend(words.iter().map(String::as_str));
    req_json(&args)
}

fn satisfy() -> Value {
    req_json(&["satisfy", "--format", "json"])
}

/// The data document embedded in a page: the text between the opening tag and its `</script>`, parsed, with the
/// escaped `</` put back. Also returns the page split around that element's text.
fn embedded(page: &str) -> (Value, String, String) {
    let start = page.find(OPEN).expect("the page has the data element") + OPEN.len();
    let end = start
        + page[start..]
            .find("</script>")
            .expect("the data element closes");
    let text = &page[start..end];
    assert!(
        !text.contains("</"),
        "the data element must escape `</` so it cannot close itself"
    );
    let value = serde_json::from_str(&text.replace("<\\/", "</")).expect("the data is JSON");
    (value, page[..start].to_string(), page[end..].to_string())
}

fn ids(value: &Value, key: &str) -> Vec<String> {
    value[key]
        .as_array()
        .unwrap_or_else(|| panic!("`{key}` is a list"))
        .iter()
        .map(|item| item["id"].as_str().expect("an id").to_string())
        .collect()
}

#[test]
fn the_explorer_page_is_current_with_the_tool() {
    let run = build(&root(), &["--check", PAGE]);
    match run.code {
        Some(0) => {}
        Some(3) => panic!("UNVERIFIABLE, not stale:\n{}", run.said),
        Some(1) => panic!(
            "docs/explorer.html is stale (regenerate with `python3 tools/explorer/build.py --out \
             docs/explorer.html`):\n{}",
            run.said
        ),
        other => panic!(
            "tools/explorer/build.py ended abnormally ({other:?}):\n{}",
            run.said
        ),
    }
}

#[test]
fn a_hand_edited_page_is_stale_and_named() {
    let copy = Copy::new("edited");
    let page = copy.path(PAGE);
    let mut text = read(&page);
    text.push_str("<!-- edited by hand -->\n");
    fs::write(&page, text).expect("edits the copy");
    let run = build(&copy.0, &["--check", PAGE]);
    assert_eq!(run.code, Some(1), "{}", run.said);
    assert!(
        run.said.contains(PAGE),
        "the stale page must be named:\n{}",
        run.said
    );
}

/// *Falsification* 1: every claim of `req.trace/1` is a node.
#[test]
fn every_claim_of_the_trace_is_a_node() {
    let (data, _, _) = embedded(&read(&root().join(PAGE)));
    let trace = trace();
    let mut want: Vec<String> = trace["nodes"]
        .as_array()
        .expect("nodes")
        .iter()
        .map(|node| node["claim_id"].as_str().expect("a claim id").to_string())
        .collect();
    want.sort();
    assert!(!want.is_empty(), "this repository holds claims");
    assert_eq!(ids(&data, "claims"), want);
    assert_eq!(data["schema"], "req.explorer/1");
    // The selection the page was built with is on the page, as `req trace` reports it.
    assert_eq!(data["selection"], trace["selection"]);
    // Every claim carries what the trace says about it.
    for node in trace["nodes"].as_array().expect("nodes") {
        let id = node["claim_id"].as_str().expect("an id");
        let mine = data["claims"]
            .as_array()
            .expect("claims")
            .iter()
            .find(|claim| claim["id"] == id)
            .expect("the claim is a node");
        assert_eq!(mine["statement"], node["statement"], "{id} statement");
        assert_eq!(mine["area"], node["area"], "{id} area");
        assert_eq!(mine["evidence"], node["evidence"], "{id} evidence");
        assert_eq!(mine["applies"], node["applies"], "{id} applies");
    }
}

/// *Falsification* 1: every `req satisfy` link is a satisfied-by edge with its own outcome, and nothing else is.
#[test]
fn every_satisfy_link_is_an_edge_with_its_outcome() {
    let (data, _, _) = embedded(&read(&root().join(PAGE)));
    let satisfy = satisfy();
    let claims = ids(&data, "claims");
    let mut want: Vec<(String, String, String)> = Vec::new();
    for link in satisfy["links"].as_array().expect("links") {
        let claim = link["claim_id"].as_str().expect("a claim").to_string();
        if claims.contains(&claim) {
            want.push((
                claim,
                link["element"].as_str().expect("an element").to_string(),
                link["outcome"].as_str().expect("an outcome").to_string(),
            ));
        }
    }
    assert!(!want.is_empty(), "this repository records design links");
    let mut got: Vec<(String, String, String)> = data["edges"]["satisfied_by"]
        .as_array()
        .expect("satisfied_by edges")
        .iter()
        .map(|edge| {
            (
                edge["claim"].as_str().expect("claim").to_string(),
                edge["design"].as_str().expect("design").to_string(),
                edge["outcome"].as_str().expect("outcome").to_string(),
            )
        })
        .collect();
    want.sort();
    got.sort();
    assert_eq!(got, want);
    // Every design node is the end of such an edge, and its id is the path req satisfy reports.
    let mut design: Vec<String> = want.iter().map(|(_, element, _)| element.clone()).collect();
    design.sort();
    design.dedup();
    assert_eq!(ids(&data, "design"), design);
}

/// *Falsification* 1 and 2: the sources, the test groups and their edges are the trace's, and every gap is a gap entry.
#[test]
fn sources_tests_and_gaps_are_the_traces() {
    let (data, _, _) = embedded(&read(&root().join(PAGE)));
    let trace = trace();
    let satisfy = satisfy();
    let linked: Vec<&str> = satisfy["links"]
        .as_array()
        .expect("links")
        .iter()
        .map(|link| link["claim_id"].as_str().expect("claim"))
        .collect();
    let mut want_gaps: Vec<(String, Vec<String>)> = Vec::new();
    let mut want_source_of: Vec<(String, String)> = Vec::new();
    let mut want_verified: Vec<(String, Vec<String>)> = Vec::new();
    let mut want_not_asked: Vec<(String, String)> = Vec::new();
    for node in trace["nodes"].as_array().expect("nodes") {
        let id = node["claim_id"].as_str().expect("id").to_string();
        let source = node["source"].as_str().unwrap_or("");
        let tests: Vec<String> = node["tests"]
            .as_array()
            .expect("tests")
            .iter()
            .map(|test| test.as_str().expect("a test id").to_string())
            .collect();
        if !source.is_empty() {
            want_source_of.push((source.to_string(), id.clone()));
        }
        if !tests.is_empty() {
            want_verified.push((id.clone(), tests.clone()));
        }
        // A claim the selection does not apply is not asked for coverage (the matrix leaves it out, ADR 0053).
        if node["applies"] != "applies" {
            continue;
        }
        let mut kinds = Vec::new();
        if !linked.contains(&id.as_str()) {
            kinds.push("no_design".to_string());
        }
        if source.is_empty() {
            kinds.push("no_source".to_string());
        }
        if tests.is_empty() {
            if node["evidence"] == "machine" {
                kinds.push("no_test".to_string());
            } else {
                want_not_asked.push((id.clone(), node["evidence"].as_str().expect("e").into()));
            }
        }
        if !kinds.is_empty() {
            kinds.sort();
            want_gaps.push((id, kinds));
        }
    }
    assert!(
        !want_gaps.is_empty(),
        "this repository has claims with a gap, or the test proves nothing"
    );
    want_gaps.sort();
    let got_gaps: Vec<(String, Vec<String>)> = data["gaps"]
        .as_array()
        .expect("gaps")
        .iter()
        .map(|gap| {
            let mut kinds: Vec<String> = gap["kinds"]
                .as_array()
                .expect("kinds")
                .iter()
                .map(|kind| kind.as_str().expect("a kind").to_string())
                .collect();
            kinds.sort();
            (gap["claim"].as_str().expect("claim").to_string(), kinds)
        })
        .collect();
    assert_eq!(got_gaps, want_gaps);
    let mut got_not_asked: Vec<(String, String)> = data["not_asked"]
        .as_array()
        .expect("not_asked")
        .iter()
        .map(|item| {
            (
                item["claim"].as_str().expect("claim").to_string(),
                item["evidence"].as_str().expect("evidence").to_string(),
            )
        })
        .collect();
    want_not_asked.sort();
    got_not_asked.sort();
    assert_eq!(got_not_asked, want_not_asked);

    // Sources are grouped by equal text; each claim with a source is the end of one source-of edge.
    let texts: std::collections::BTreeMap<String, String> = data["sources"]
        .as_array()
        .expect("sources")
        .iter()
        .map(|source| {
            (
                source["id"].as_str().expect("id").to_string(),
                source["text"].as_str().expect("text").to_string(),
            )
        })
        .collect();
    let mut got_source_of: Vec<(String, String)> = data["edges"]["source_of"]
        .as_array()
        .expect("source_of")
        .iter()
        .map(|edge| {
            (
                texts[edge["source"].as_str().expect("source")].clone(),
                edge["claim"].as_str().expect("claim").to_string(),
            )
        })
        .collect();
    want_source_of.sort();
    got_source_of.sort();
    assert_eq!(got_source_of, want_source_of);
    let distinct: std::collections::BTreeSet<&String> = texts.values().collect();
    assert_eq!(distinct.len(), texts.len(), "equal text is one source");

    // One test group per claim with tests, holding that claim's ids in order, joined by a verified-by edge.
    let mut got_verified: Vec<(String, Vec<String>)> = data["tests"]
        .as_array()
        .expect("tests")
        .iter()
        .map(|group| {
            (
                group["claim"].as_str().expect("claim").to_string(),
                group["ids"]
                    .as_array()
                    .expect("ids")
                    .iter()
                    .map(|id| id.as_str().expect("test id").to_string())
                    .collect(),
            )
        })
        .collect();
    got_verified.sort();
    want_verified.sort();
    assert_eq!(got_verified, want_verified);
    assert_eq!(
        data["edges"]["verified_by"]
            .as_array()
            .expect("verified_by")
            .len(),
        want_verified.len()
    );
}

/// *Falsification* 3: nothing is fetched. `<a href>` may point anywhere; a script, style, font, image or request may not.
fn leaks(text: &str) -> Vec<String> {
    fn remote(value: &str) -> bool {
        let value = value.trim().trim_matches(|c| c == '"' || c == '\'');
        let lower = value.to_ascii_lowercase();
        lower.starts_with("http://")
            || lower.starts_with("https://")
            || lower.starts_with("//")
            || lower.starts_with("ws:")
            || lower.starts_with("wss:")
    }
    // `n` characters from byte `at` (the template holds non-ASCII text, so never slice by bytes).
    fn from(text: &str, at: usize, n: usize) -> String {
        text[at..].chars().take(n).collect()
    }
    let mut found = Vec::new();
    let lower = text.to_ascii_lowercase();
    for key in ["src=", "srcset=", "poster=", "data-src="] {
        for (at, _) in lower.match_indices(key) {
            // Only an attribute (a space or a tag name before it), not a JS property such as `x.src=`.
            let before = lower[..at].chars().next_back().unwrap_or(' ');
            if before == '.' || before.is_ascii_alphanumeric() || before == '_' {
                continue;
            }
            let value = from(text, at + key.len(), 160);
            if remote(&value) {
                found.push(from(text, at, 70));
            }
        }
    }
    for (at, _) in lower.match_indices("<link") {
        let tag = &text[at..at + text[at..].find('>').unwrap_or(text.len() - at)];
        let tag_lower = tag.to_ascii_lowercase();
        if let Some(h) = tag_lower.find("href=")
            && remote(&from(tag, h + 5, 160))
        {
            found.push(tag.to_string());
        }
    }
    for (at, _) in lower.match_indices("url(") {
        if remote(&from(text, at + 4, 80)) {
            found.push(from(text, at, 40));
        }
    }
    // Whitespace is dropped for the needles, so `new  Worker (` and `import (` are seen as `newworker(` and `import(`.
    let squeezed: String = lower.chars().filter(|c| !c.is_whitespace()).collect();
    for needle in [
        "@import",
        "fetch(",
        "xmlhttprequest",
        "websocket(",
        "eventsource(",
        "sendbeacon",
        "importscripts",
        "newworker(",
        "newsharedworker(",
        "serviceworker",
        "import(",
        // A page that frames or embeds another document is a page that loads one.
        "<iframe",
        "<frame",
        "<object",
        "<embed",
    ] {
        if squeezed.contains(needle) {
            found.push(needle.to_string());
        }
    }
    for (at, _) in lower.match_indices("data=") {
        let before = lower[..at].chars().next_back().unwrap_or(' ');
        if !(before == '.' || before.is_ascii_alphanumeric() || before == '_' || before == '-')
            && remote(&from(text, at + 5, 160))
        {
            found.push(from(text, at, 70));
        }
    }
    found
}

#[test]
fn the_page_loads_nothing_over_the_network() {
    let page = read(&root().join(PAGE));
    let (_, before, after) = embedded(&page);
    // The data are claim statements and file names, which may name a URL; what runs is the template around them.
    let leaked = leaks(&format!("{before}{after}"));
    assert!(
        leaked.is_empty(),
        "the page reaches the network: {leaked:?}"
    );
    let template = read(&root().join(TEMPLATE));
    let leaked = leaks(&template);
    assert!(
        leaked.is_empty(),
        "the template reaches the network: {leaked:?}"
    );
    // The detector sees what it should: it is not blind to a CDN script.
    assert!(!leaks("<script src=\"https://cdn.example.org/x.js\"></script>").is_empty());
    assert!(!leaks("<link rel=\"stylesheet\" href=\"//cdn.example.org/x.css\">").is_empty());
    assert!(!leaks("a{background:url(https://example.org/x.png)}").is_empty());
    assert!(leaks("<a href=\"https://example.org/\">x</a>").is_empty());
    // Nor to the other ways a page reaches out.
    for sample in [
        "new Worker('https://cdn.example.org/w.js')",
        "new  SharedWorker ('w.js')",
        "navigator.serviceWorker.register('/sw.js')",
        "import('https://cdn.example.org/m.js')",
        "import ('./m.js')",
        "<iframe src=\"https://example.org/\"></iframe>",
        "<iframe srcdoc=\"x\"></iframe>",
        "<object data=\"https://example.org/x.swf\"></object>",
        "<embed src=\"//example.org/x\">",
        "importScripts('x.js')",
    ] {
        assert!(!leaks(sample).is_empty(), "the detector missed: {sample}");
    }
    assert!(leaks("an important(thing) and data-k=\"x\"").is_empty());
}

/// *Falsification* 4, and the template contract: the page is the template with the data inserted, nothing else.
#[test]
fn the_page_is_the_template_around_the_data_and_two_builds_agree() {
    let template = read(&root().join(TEMPLATE));
    assert_eq!(
        template.matches(TOKEN).count(),
        1,
        "the template names the data's place exactly once"
    );
    assert!(
        template.contains(&format!("{OPEN}{TOKEN}</script>")),
        "the token sits inside the data element"
    );
    let page = read(&root().join(PAGE));
    let (_, before, after) = embedded(&page);
    let (template_before, template_after) = template.split_once(TOKEN).expect("the token");
    assert_eq!(
        before, template_before,
        "the bytes before the data are the template's"
    );
    assert_eq!(
        after, template_after,
        "the bytes after the data are the template's"
    );

    let dir = std::env::temp_dir().join(format!("req-explorer-twice-{}", std::process::id()));
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(&dir).expect("makes the dir");
    let first = dir.join("first.html");
    let second = dir.join("second.html");
    for out in [&first, &second] {
        let run = build(&root(), &["--out", out.to_str().expect("a path")]);
        assert_eq!(run.code, Some(0), "{}", run.said);
    }
    let a = fs::read(&first).expect("first build");
    let b = fs::read(&second).expect("second build");
    let _ = fs::remove_dir_all(&dir);
    assert_eq!(a, b, "two builds over one repository differ");
    assert_eq!(
        a,
        page.as_bytes(),
        "a build is the committed page (the check above, byte for byte)"
    );
}

/// ADR 0054 decision 6: the committed page is a function of the repository, so it holds no test outcome.
#[test]
fn the_committed_data_carries_no_test_outcome() {
    let (data, _, _) = embedded(&read(&root().join(PAGE)));
    for group in data["tests"].as_array().expect("tests") {
        let keys: Vec<&String> = group.as_object().expect("a group").keys().collect();
        assert_eq!(keys, ["claim", "id", "ids"], "a test group is ids only");
    }
    for edge in data["edges"]["verified_by"].as_array().expect("edges") {
        let keys: Vec<&String> = edge.as_object().expect("an edge").keys().collect();
        assert_eq!(
            keys,
            ["claim", "group"],
            "a verified-by edge has no outcome"
        );
    }
    let text = serde_json::to_string(&data).expect("serializes");
    // A test outcome word as a whole JSON string: never a key or a value (a file called src/junit.rs is a design element,
    // so the bare word `junit` is not what is looked for).
    for word in [
        "\"passed\"",
        "\"failed\"",
        "\"skipped\"",
        "\"not_found\"",
        "\"test_report\"",
    ] {
        assert!(
            !text.contains(word),
            "a test outcome reached the data: {word}"
        );
    }
    let builder = read(&root().join("tools/explorer/build.py"));
    assert!(
        !builder.contains("--test-report") && !builder.contains("junit"),
        "the builder takes no test report: it builds the committed page"
    );
}

/// A design file `req satisfy` cannot read is not judged: the check is UNVERIFIABLE (exit 3), never current, and it
/// names the file (as O-3-fix did for the architecture page).
#[test]
fn an_unreadable_design_file_is_unverifiable_never_current() {
    use std::os::unix::fs::PermissionsExt;
    let copy = Copy::new("unreadable");
    let before = read(&copy.path(PAGE));
    let audit = copy.path("src/audit.rs");
    fs::set_permissions(&audit, fs::Permissions::from_mode(0o000)).expect("chmod 000 the copy");
    assert!(
        fs::read(&audit).is_err(),
        "this test needs a user that mode 000 locks out (not root)"
    );
    let check = build(&copy.0, &["--check", PAGE]);
    assert_eq!(check.code, Some(3), "{}", check.said);
    assert!(
        check.said.contains("UNVERIFIABLE") && check.said.contains("src/audit.rs"),
        "the unreadable file must be named:\n{}",
        check.said
    );
    let out = build(&copy.0, &["--out", PAGE]);
    assert_eq!(out.code, Some(3), "{}", out.said);
    assert_eq!(
        before,
        read(&copy.path(PAGE)),
        "an UNVERIFIABLE run must not rewrite the committed page"
    );
}

